<header class="page-header"><div><h1><?= e(t('Starter packs')) ?></h1><p class="muted"><?= e(t('Preview editable plans for your selected roles. Installing adds unfinished tasks, habits and a goal while keeping your other roles.')) ?></p></div><a href="/settings/workspace"><?= e(t('Back')) ?></a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php $roles=PersonaService::selectedRoles();$availablePacks=array_filter(TemplatePackService::catalog(),fn($pack)=>!$roles||in_array($pack['persona'],$roles,true));if(!$availablePacks): ?><p class="card"><?= e(t('No starter pack is available for these roles yet. You can create your own tasks and goals.')) ?></p><?php endif; ?>
<?php foreach($availablePacks as $packId=>$pack): ?><section class="card"><h2><?= e(t($pack['name'])) ?></h2><p><strong><?= e(t('Goal')) ?>:</strong> <?= e(t($pack['goal'])) ?></p><h3><?= e(t('Tasks')) ?></h3><ul><?php foreach($pack['tasks'] as $title): ?><li><?= e(t($title)) ?></li><?php endforeach; ?></ul><h3><?= e(t('Habits')) ?></h3><ul><?php foreach($pack['habits'] as $title): ?><li><?= e(t($title)) ?></li><?php endforeach; ?></ul><?php if($pack['modules']): ?><p><?= e(t('Editable subject placeholders:')) ?> <?= e(implode(', ',array_map('t',$pack['modules']))) ?>. <?= e(t('Credits start at zero; grades remain unset.')) ?></p><?php endif; ?><?php if(TemplatePackService::installed($packId)): ?><p class="badge"><?= e(t('Installed')) ?></p><?php else: ?><form method="post" action="/settings/workspace/packs" hx-boost="false"><?= csrf_field() ?><input type="hidden" name="pack" value="<?= e($packId) ?>"><button><?= e(t('Install starter pack')) ?></button></form><?php endif; ?></section><?php endforeach; ?>
